// The project's decisions as a plain Markdown file in its own .clawd-hq folder, read and written by people and by this plugin alike.
// Pure: no file is touched here. One line per entry, so a hand edit is a one-line change in git.
import { SAVED_CHARS, fit } from './desk'
import type { Memory } from '../types'

export const LOGBOOK_FILE = '.clawd-hq/decisions.md'

/** The most that is read of one line: above anything the plugin writes (a question, an arrow and its answer), so a read never cuts what a save wrote. */
const LINE_CHARS = SAVED_CHARS + 1000


const HEADER = [
  '# Clawd HQ decisions',
  '',
  'What you decided and what your agents chose, one line each, oldest first.',
  'You can edit this file by hand: add a line starting with "- " and it is picked up.',
  'Other lines, such as notes and headings, are left as they are.',
  '',
].join('\n')

const KINDS = ['decision', 'choice'] as const
const SOURCES = ['desk', 'report', 'clawd'] as const

const stamp = (at: number) => new Date(at).toISOString().slice(0, 16).replace('T', ' ')
const FULL = /^- (M\d+) · (\d{4}-\d{2}-\d{2} \d{2}:\d{2}) · (\S+) · (.+?) · (\S+) · (.*)$/

const oneOf = <T extends string>(list: readonly T[], value: string, otherwise: T): T => (list as readonly string[]).includes(value) ? (value as T) : otherwise

const line = (m: Memory) => `- ${m.id} · ${stamp(m.at)} · ${m.kind} · ${m.by.replace(/ · /g, ' - ')} · ${m.source} · ${m.text}`

/** The file's whole text for these entries, in the order given. */
export function toMarkdown(list: readonly Memory[]): string {
  return `${HEADER}${list.map(m => `${line(m)}\n`).join('')}`
}

/** One entry the file holds: the line it is on, the entry, and whether the line is in the form this plugin writes. */
export type Parsed = { line: number; memory: Memory; isFull: boolean }

/**
 * The entries a file holds. A line in the form this plugin writes comes back as it was (to the minute); any other
 * "- text" line is a decision of yours, dated `now`, with the next free id. Everything else is ignored.
 */
export function parseEntries(text: string, now: number): Parsed[] {
  const out: Parsed[] = []
  const taken = new Set<string>()
  const lines = text.split(/\r?\n/)
  const isEntry = (l: string) => l.startsWith('- ') && l.slice(2).trim() !== ''
  let next = lines.reduce((n, l) => Math.max(n, isEntry(l) ? Number(FULL.exec(l)?.[1]?.slice(1)) || 0 : 0), 0)
  const fresh = () => { next += 1; return `M${next}` }
  lines.forEach((raw, i) => {
    if (!isEntry(raw)) return
    const m = FULL.exec(raw)
    const at = m ? Date.parse(`${m[2]!.replace(' ', 'T')}:00Z`) : NaN
    const body = fit(m ? m[6]! : raw.slice(2), LINE_CHARS)
    if (body === '') return
    const id = m && !taken.has(m[1]!) ? m[1]! : fresh()
    taken.add(id)
    const isFull = m !== null && Number.isFinite(at)
    out.push({
      line: i, isFull,
      memory: isFull
        ? { id, kind: oneOf(KINDS, m![3]!, 'decision'), text: body, by: m![4]!, at, source: oneOf(SOURCES, m![5]!, 'desk') }
        : { id, kind: 'decision', text: body, by: 'CEO', at: now, source: 'desk' },
    })
  })
  return out
}

export const fromMarkdown = (text: string, now: number): Memory[] => parseEntries(text, now).map(p => p.memory)

const same = (a: Memory, b: Memory) => a.id === b.id && a.kind === b.kind && a.text === b.text && a.by === b.by && a.source === b.source && a.at === b.at

/**
 * The file's text after a save: its own lines stay exactly as they were (notes, headings, an entry that did not
 * change); an entry gone from `after` loses its line; one that changed, or that you wrote by hand without an id, is
 * rewritten in place; a new one goes at the end. An empty file becomes the readable header and the entries.
 */
export function mergeMarkdown(existing: string, after: readonly Memory[], now: number): string {
  if (existing.trim() === '') return toMarkdown(after)
  const wanted = new Map(after.map(m => [m.id, m]))
  const on = new Map(parseEntries(existing, now).map(p => [p.line, p]))
  const seen = new Set<string>()
  const out: string[] = []
  existing.split(/\r?\n/).forEach((raw, i) => {
    const p = on.get(i)
    if (!p) { out.push(raw); return }
    const want = wanted.get(p.memory.id)
    if (!want || seen.has(want.id)) return
    seen.add(want.id)
    out.push(p.isFull && same(p.memory, want) ? raw : line(want))
  })
  while (out.length > 0 && out[out.length - 1] === '') out.pop()
  return `${[...out, ...after.filter(m => !seen.has(m.id)).map(line)].join('\n')}\n`
}

// ---- The file itself, through plain calls register.tsx hands in (`$` never leaves that file) ----

export type LogbookIo = {
  /** The project folder; empty when the session has none. */
  cwd: string
  exists: (path: string) => Promise<boolean>
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  now: () => Promise<number>
  /** What this session holds, for when the file cannot give the list. */
  held: () => Promise<Memory[]>
}

export type Logbook = { text: string; list: Memory[]; isWritable: boolean }

/**
 * The file's text and entries; where there is no file, what this session holds. When the file's state cannot be
 * known (the check or the read failed), it is not safe to write over.
 */
export async function loadLogbook(io: LogbookIo): Promise<Logbook> {
  if (!io.cwd) return { text: '', list: await io.held(), isWritable: false }
  const path = `${io.cwd}/${LOGBOOK_FILE}`
  try {
    if (!(await io.exists(path))) return { text: '', list: await io.held(), isWritable: true }
    const text = await io.read(path)
    return { text, list: fromMarkdown(text, await io.now()), isWritable: true }
  } catch {
    return { text: '', list: await io.held(), isWritable: false }
  }
}

/** Writes `list` into the file as it was loaded. False when it did not land; with no project folder there is nothing to write. */
export async function saveLogbook(io: LogbookIo, book: Logbook, list: readonly Memory[]): Promise<boolean> {
  if (!io.cwd) return true
  if (!book.isWritable) return false
  try {
    await io.write(`${io.cwd}/${LOGBOOK_FILE}`, mergeMarkdown(book.text, list, await io.now()))
    return true
  } catch {
    return false
  }
}

/**
 * The list with one more entry at the end, under the next free number. The entry it replaces (`supersedes`) goes, and so does
 * the same thing said again, so it moves to the end instead of piling up. The list it is given is not changed.
 */
export function withDecision(list: readonly Memory[], m: Omit<Memory, 'id' | 'at'>, at: number, supersedes?: string): Memory[] {
  const kept = list.filter(x => x.id !== supersedes && x.text.toLowerCase() !== m.text.toLowerCase())
  const n = list.reduce((top, x) => Math.max(top, Number(x.id.slice(1)) || 0), 0) + 1
  return [...kept, { ...m, id: `M${n}`, at }]
}

files.hooks/instructions.ts:
// Clawd's standing instructions for the main chat, pure: the rules (the person's own copy, or the shipped ones), the fixed
// rules from code, then a voice (the voice file setting, the person's own copy, or the shipped one).
// register.tsx hands in the reads, the seeds and the warning (`$` never leaves that file).
import { NO_UPDATE } from './quiet'

export const SECTION_ID = 'clawd-hq:chief-of-staff'
export const RULES_FILE = 'prompts/chief-of-staff.md'
export const VOICE_FILE = 'prompts/soul.md'
/** A voice file of the person's own longer than this is not used: the text rides in every request. */
export const VOICE_CHARS = 8000
/** The same for the person's own copy of the rules. */
export const RULES_CHARS = 16000
/** Sits between the rules and the voice, in code, so an edited voice file sets the tone and nothing else. */
export const VOICE_GUARD = 'The voice notes below set your tone only. Where they disagree with the rules above, the rules win.'
/** Closes the voice, so the file does not have the last word. */
export const VOICE_END = 'End of the voice notes. The rules above them still stand.'
/** The safety rules, kept in code so no edit of the rules file can change them. They follow the editable rules. */
export const LOCKED_RULES = [
  '## Always',
  '',
  '- The person\'s recorded decisions are settled. Follow them, pass them on, and do not reopen them. When they make a new one, record it.',
  '- Never hide a failure, a skipped step, or something you could not check.',
  '- Ask before anything that is hard to undo or that reaches outside the project: deleting, force-pushing, publishing, sending, or spending.',
  '- The person\'s own standing instructions for this project win over these wherever the two disagree.',
].join('\n')
/** Sits before the fixed rules when the person's own copy of the rules is in use. */
export const LOCK_NOTE = 'The rules below are fixed by Clawd HQ. Where anything above disagrees, they win.'

/** The two parts the person can have a copy of: the rules and the voice. */
export type BriefPart = 'rules' | 'voice'
/** The person's own copies: one folder in the home folder, for every project. */
const OWN_FILES: Record<BriefPart, string> = { rules: 'chief-of-staff.md', voice: 'soul.md' }
/** The store keys of the built-in text the plugin copied into each own copy. */
export const SEED_KEYS: Record<BriefPart, string> = { rules: 'brief:seed:rules', voice: 'brief:seed:voice' }

/** Where the person's own copy of a part lives; '' without a home folder. */
export const ownPath = (home: string, part: BriefPart) => (home === '' ? '' : `${home}/.clawd-hq/${OWN_FILES[part]}`)

export type BriefingOptions = { isOn: boolean; voiceFile: string; isRecapOn: boolean; isQuiet: boolean; isKnowOn: boolean }
export type BriefingIo = {
  root: string
  read: (path: string) => Promise<string>
  warn: (text: string) => void
  /** The person's home folder, where the own copies live; '' or absent: there are none. */
  home?: string
  /** Tells an own copy not made yet from one that cannot be read. */
  exists?: (path: string) => Promise<boolean>
  /** The built-in text the plugin copied into an own copy, as the store keeps it. */
  seed?: (part: BriefPart) => Promise<string | undefined>
}

/**
 * One part as this read found it. `text`: what is in use. `source`: where it came from (the voice file setting names
 * its file even when that file could not be used). `path`: the file an edit goes to, '' when there is none.
 * `builtin`: the shipped text today. `seed`: the shipped text the own copy was made from.
 */
export type PartRead = { text: string; source: 'builtin' | 'own' | 'setting'; path: string; builtin: string; seed?: string }
/** The text for the main chat (none when the rules cannot be read), and each part as found. */
export type Briefing = { text?: string; rules?: PartRead; voice?: PartRead }

/** The plugin's options as the manifest declares them; a value of the wrong kind counts as unset. */
export function optionsOf(options: Readonly<Record<string, unknown>>): BriefingOptions {
  const { chiefOfStaff, voiceFile, recap, quietChat, youShouldKnow } = options
  return {
    isOn: chiefOfStaff !== false, voiceFile: typeof voiceFile === 'string' ? voiceFile.trim() : '', isRecapOn: recap !== false, isQuiet: quietChat !== false,
    isKnowOn: youShouldKnow !== false,
  }
}

/** A bare session keeps its one-line prompt, and a teammate is not the chief of staff. */
export const isBriefed = (traits: readonly string[]) => !traits.some(t => t === 'bare' || t === 'teammate')

const readOr = (io: BriefingIo, path: string) => io.read(path).then(text => text.trim(), () => undefined)

/** A word to the person. A warning that itself fails must not cost the briefing, so it is let go. */
function tell(io: BriefingIo, text: string) {
  try { io.warn(text) } catch { /* nothing more can be said */ }
}

const seedOf = async (io: BriefingIo, part: BriefPart) => {
  const seed = await io.seed?.(part).catch(() => undefined)
  return typeof seed === 'string' ? seed.trim() : undefined
}

const WHAT: Record<BriefPart, string> = { rules: 'instructions', voice: 'voice' }

/**
 * The person's own copy when it can be used: there, not empty, within `limit`, and edited (a copy that still equals its
 * seed follows the built-in text). A copy that is there but cannot be read, or is too long, is a word to the person.
 */
async function ownOf(io: BriefingIo, part: BriefPart, limit: number): Promise<{ text?: string; seed?: string }> {
  const path = ownPath(io.home ?? '', part)
  if (path === '') return {}
  const seed = await seedOf(io, part)
  const own = await readOr(io, path)
  const fallback = `Clawd uses his built-in ${WHAT[part]} this session.`
  if (own === undefined) {
    if (await (io.exists?.(path) ?? Promise.resolve(false)).catch(() => false)) tell(io, `Your own copy ${path} could not be read. ${fallback}`)
    return { seed }
  }
  if (own === '' || own === seed) return { seed }
  if (own.length > limit) {
    tell(io, `Your own copy ${path} is over ${limit} characters. ${fallback}`)
    return { seed }
  }
  return { text: own, seed }
}

/** The rules: the person's edited copy, else the shipped file. None when the shipped file cannot be read. */
async function rulesOf(io: BriefingIo): Promise<PartRead | undefined> {
  const builtin = await readOr(io, `${io.root}/${RULES_FILE}`)
  if (builtin === undefined || builtin === '') return undefined
  const own = await ownOf(io, 'rules', RULES_CHARS)
  const base = { path: ownPath(io.home ?? '', 'rules'), builtin, ...(own.seed === undefined ? {} : { seed: own.seed }) }
  return own.text === undefined ? { text: builtin, source: 'builtin', ...base } : { text: own.text, source: 'own', ...base }
}

/** The voice: the setting's file when it can be used (it wins), else the person's edited copy, else the shipped one, with a word to the person about why. */
async function voiceOf(io: BriefingIo, voiceFile: string): Promise<PartRead> {
  const shipped = (await readOr(io, `${io.root}/${VOICE_FILE}`)) ?? ''
  const noShipped = () => { if (shipped === '') tell(io, 'Clawd HQ could not read its built-in voice. Clawd follows his rules without it this session.') }
  if (voiceFile !== '') {
    const own = await readOr(io, voiceFile)
    if (own !== undefined && own !== '' && own.length <= VOICE_CHARS) return { text: own, source: 'setting', path: voiceFile, builtin: shipped }
    const why = own === undefined ? 'could not be read (check the full path)' : own === '' ? 'is empty' : `is over ${VOICE_CHARS} characters`
    tell(io, `Your voice file ${voiceFile} ${why}. Clawd uses his built-in voice this session.`)
    noShipped()
    return { text: shipped, source: 'setting', path: voiceFile, builtin: shipped }
  }
  const own = await ownOf(io, 'voice', VOICE_CHARS)
  const base = { path: ownPath(io.home ?? '', 'voice'), builtin: shipped, ...(own.seed === undefined ? {} : { seed: own.seed }) }
  if (own.text !== undefined) return { text: own.text, source: 'own', ...base }
  noShipped()
  return { text: shipped, source: 'builtin', ...base }
}

/** The main chat's text: the rules, the fixed rules (with a line saying they win, after an own copy), then the voice between its two guard lines. */
function textOf(rules: PartRead, voice: PartRead, isQuiet: boolean): string {
  const all = rules.source === 'own' ? [rules.text, LOCK_NOTE, LOCKED_RULES].join('\n\n') : `${rules.text}\n\n${LOCKED_RULES}`
  // The line that asks for the no-update mark is only of use where the chat hides the mark.
  const kept = isQuiet ? all : all.split('\n').filter(line => !line.includes(NO_UPDATE)).join('\n')
  return voice.text === '' ? kept : [kept, VOICE_GUARD, voice.text, VOICE_END].join('\n\n')
}

/** Reads both parts and puts the text together. With the shipped rules unreadable, nothing at all, and the person is told. */
export async function readBriefing(io: BriefingIo, opts: { voiceFile: string; isQuiet: boolean }): Promise<Briefing> {
  const rules = await rulesOf(io)
  if (rules === undefined) {
    tell(io, 'Clawd HQ could not read its chief of staff instructions. Claude runs as usual this session.')
    return {}
  }
  const voice = await voiceOf(io, opts.voiceFile)
  return { text: textOf(rules, voice, opts.isQuiet), rules, voice }
}

/** The text added to the main chat's instructions, or nothing when the rules cannot be read. With the quiet chat off, the rule about the no-update mark is left out. */
export const loadBriefing = async (io: BriefingIo, voiceFile: string, isQuiet = true): Promise<string | undefined> =>
  (await readBriefing(io, { voiceFile, isQuiet })).text

files.hooks/clawd-edit.ts:
// The edit button for Clawd's instructions in the Settings tab, pure: the ready-made prompts, the note Claude gets with them, the guard on the plugin's own
// files, and the steps behind the buttons. register.tsx hands in every call as `io`.
import type { ClawdBrief, ClawdPartView } from '../types'
import { RULES_CHARS, RULES_FILE, VOICE_CHARS, VOICE_FILE, ownPath, readBriefing } from './instructions'
import type { BriefPart, Briefing, BriefingIo, PartRead } from './instructions'
import { reasonOf } from './state'

// ---- The prompt, and what Claude is told with it ----

const OPENING: Record<BriefPart, string> = { rules: 'Edit Clawd\'s instructions', voice: 'Edit Clawd\'s voice notes' }

/** The line put in the prompt box, for the person to finish. */
export const promptOf = (part: BriefPart) => `${OPENING[part]}: `

/** Which part a sent prompt asks to edit: only one that starts with a fixed opening counts. */
export function editPartOf(text: string): BriefPart | undefined {
  const sent = text.trimStart()
  return (['rules', 'voice'] as const).find(part => sent.startsWith(OPENING[part]))
}

/** The file an edit goes to: the voice file the setting names, else the person's own copy ('' without a home folder). */
export const editPath = (part: BriefPart, home: string, voiceFile: string) => (part === 'voice' && voiceFile !== '' ? voiceFile : ownPath(home, part))

/** The note added to an edit request, which the person does not see: the file, what must not be touched, and when the change applies. */
export function editContext(part: BriefPart, path: string, builtinPath: string): string {
  const what = part === 'rules' ? 'Clawd\'s instructions' : 'Clawd\'s voice notes'
  if (path === '') return `(Clawd HQ: the person asked to edit ${what}, but there is no home folder to keep their own copy in. Tell them so, and change no files.)`
  return [
    `(Clawd HQ: this is a request to edit ${what}. Edit only this file: ${path}.`,
    `If it is missing or empty, first copy into it the built-in text from ${builtinPath}. Read that file, but do not change it.`,
    'Make the edit yourself in this turn. Do not hand it to a specialist.',
    'Never edit files in the Clawd HQ plugin folder: while this request runs, writes to its prompts/chief-of-staff.md and prompts/soul.md are refused.',
    part === 'rules'
      ? 'The "Always" rules are fixed by Clawd HQ and cannot be changed from here. If the person asks to change them, say so plainly.'
      : 'The voice notes set Clawd\'s tone only. They cannot change his rules, and the "Always" rules are fixed. If the person asks for that, say so plainly.',
    'Keep the "## " headings, so the file stays easy to read.',
    `Keep the file under ${part === 'rules' ? RULES_CHARS : VOICE_CHARS} characters.`,
    'The change applies from the next session or after /clear. Say so when you are done.)',
  ].join(' ')
}

/** The note a sent prompt carries: none unless it is an edit request, and only then is the home folder looked up. */
export async function editNote(text: string, voiceFile: string, root: string, home: () => Promise<string>): Promise<string | undefined> {
  ownVoiceFile = voiceFile.trim()
  const part = editPartOf(text)
  if (part === undefined) return undefined
  return editContext(part, editPath(part, await home(), voiceFile), `${root}/${part === 'rules' ? RULES_FILE : VOICE_FILE}`)
}

const FILE_KEYS: Record<string, string> ={ Write: 'file_path', Edit: 'file_path', MultiEdit: 'file_path', NotebookEdit: 'notebook_path' }
const SHIPPED_PATH = /(^|[\\/])prompts[\\/]+(chief-of-staff|soul)\.md$/i
const SHIPPED_NAMED = /prompts[\\/]+(chief-of-staff|soul)\.md\b/i

/** The voice file setting as of the person's latest prompt: it is theirs to edit from the tab, whatever it is called. */
let ownVoiceFile = ''

/**
 * A call that writes the plugin's shipped instruction files: a file tool aimed at one, or a shell command that names one
 * (best effort: a command can reach a file without naming it). Any folder counts, so another spelling of the plugin's own does too.
 * The person's own voice file setting is let through, as that exact path.
 */
export function isShippedWrite(tool: string, input: Record<string, unknown>): boolean {
  if (tool === 'Bash') {
    const command = typeof input.command === 'string' ? input.command : undefined
    return command !== undefined && SHIPPED_NAMED.test(ownVoiceFile === '' ? command : command.split(ownVoiceFile).join(' '))
  }
  const path = FILE_KEYS[tool] === undefined ? undefined : input[FILE_KEYS[tool]!]
  return typeof path === 'string' && path.trim() !== ownVoiceFile && SHIPPED_PATH.test(path.trim())
}

export const SHIPPED_DENY = 'Refused by Clawd HQ: during a request to edit Clawd\'s instructions, the plugin\'s built-in files stay as they are. Edit the person\'s own copy named in the request instead.'

/**
 * What stands in for the guard when the hook holding it fails before passing the call on. During an edit request a
 * write to the built-in files is refused, and so is one that cannot be judged; anything else, and every call outside
 * an edit request, goes on as it would have.
 */
export function guardOnCrash(isEditTurn: boolean, tool: string, input: Record<string, unknown>): 'deny' | 'pass' {
  if (!isEditTurn) return 'pass'
  try {
    return isShippedWrite(tool, input) ? 'deny' : 'pass'
  } catch {
    return 'deny'
  }
}

// ---- What the tab shows ----

/** One part for the tab: the text now, and whether it moved since this session loaded it or since its copy was made. */
export function partView(now: PartRead, loaded: PartRead | undefined): ClawdPartView {
  return {
    text: now.text, source: now.source, path: now.path,
    isChanged: loaded !== undefined && loaded.text !== now.text,
    isNewer: now.source === 'own' && now.seed !== undefined && now.seed !== now.builtin,
  }
}

// ---- The steps behind the buttons ----

export type ClawdIo = {
  /** The setting "Clawd runs the chat". */
  isOn: boolean
  /** The voice file setting; '' when unset. */
  voiceFile: string
  /** The reads the briefing makes; the tab reads the same way, without a word to the person. */
  briefing: BriefingIo
  /** What this session's chat was given; nothing before the first request, or with Clawd off. */
  loaded: () => Promise<Briefing | undefined>
  write: (path: string, text: string) => Promise<void>
  setSeed: (part: BriefPart, text: string) => Promise<unknown>
  promptRead: () => Promise<{ text: string }>
  fill: (text: string) => Promise<{ isFilled: boolean; refusal?: 'no_composer' | 'dialog' }>
  get: () => Promise<ClawdBrief>
  set: (fn: (b: ClawdBrief) => ClawdBrief) => Promise<unknown>
}

export const BOX_BUSY = 'Your prompt box already has text. Send or clear it, then press again.'
export const DIALOG_OPEN = 'A question is open in the chat. Answer it, then press again.'
const NO_HOME = 'Clawd HQ cannot find your home folder, so there is no place for your own copy.'
export const readyText = (isTerminal: boolean) =>
  (isTerminal ? 'Ready in your prompt box. Press Esc, finish the sentence, then Enter.' : 'Ready in your prompt box. Finish the sentence, then send it.')

const readNow = (io: ClawdIo) => readBriefing({ ...io.briefing, warn: () => undefined }, { voiceFile: io.voiceFile, isQuiet: true })
const say = (io: ClawdIo, notice: NonNullable<ClawdBrief['notice']>) => io.set(b => ({ ...b, notice }))

/** The tab's one amber line for a read that failed. */
export const readFailedLine = (reason: string) => `Couldn't read Clawd's instructions: ${reason}`

/** A read that failed, kept with its reason beside what the tab showed, so the tab says so instead of staying empty. A refresh that works rebuilds the brief without it. */
export const readFailed = (b: ClawdBrief, err: unknown): ClawdBrief => ({ ...b, readError: reasonOf(err) })

/** Shows both parts as they are now. `isFresh` (after a turn) also drops the word the last button left. */
export async function refreshClawd(io: ClawdIo, isFresh: boolean) {
  const [now, loaded] = [await readNow(io), await io.loaded()]
  const view = (part: BriefPart) => {
    const p = now[part]
    return p === undefined ? {} : { [part]: partView(p, loaded?.[part]) }
  }
  await io.set(b => ({ isOn: io.isOn, ...view('rules'), ...view('voice'), ...(!isFresh && b.notice !== undefined ? { notice: b.notice } : {}) }))
}

/**
 * Makes sure the own copy holds text to edit: one not there, empty, or never edited while the built-in text moved on gets
 * today's built-in text, and that text is kept as its seed. An edited copy is never written over. A word for the person when it cannot be done.
 */
async function ensureCopy(io: ClawdIo, part: BriefPart, p: PartRead): Promise<string | undefined> {
  const current = await io.briefing.read(p.path).then(t => t.trim(), () => undefined)
  const isThere = current !== undefined || (await (io.briefing.exists?.(p.path) ?? Promise.resolve(false)).catch(() => false))
  if (current === undefined && isThere) return `Your own copy at ${p.path} could not be read, so nothing was put in your prompt box.`
  if (current !== undefined && current !== '' && !(current === p.seed && p.seed !== p.builtin)) return undefined
  try {
    await io.write(p.path, `${p.builtin}\n`)
    await io.setSeed(part, p.builtin)
    return undefined
  } catch {
    return `Could not make your own copy at ${p.path}, so nothing was put in your prompt box.`
  }
}

/** The word after a fill: ready, a question in the way, or the line to type where no box took it. Nothing is ever sent. */
function filledNotice(r: { isFilled: boolean; refusal?: string }, line: string, isTerminal: boolean): NonNullable<ClawdBrief['notice']> {
  if (r.isFilled) return { text: readyText(isTerminal) }
  return r.refusal === 'dialog' ? { text: DIALOG_OPEN } : { text: 'Type this in the chat:', line }
}

async function editClawd(io: ClawdIo, part: BriefPart, isTerminal: boolean) {
  const box = await io.promptRead().catch(() => ({ text: '' }))
  if (box.text.trim() !== '') return say(io, { text: BOX_BUSY })
  const p = (await readNow(io))[part]
  if (p === undefined) return say(io, { text: 'Clawd HQ could not read its built-in instructions, so there is nothing to edit.' })
  if (p.path === '') return say(io, { text: NO_HOME })
  const problem = p.source === 'setting' ? undefined : await ensureCopy(io, part, p)
  if (problem !== undefined) return say(io, { text: problem })
  const line = promptOf(part)
  const r = await io.fill(line).catch(() => ({ isFilled: false }))
  await say(io, filledNotice(r, line, isTerminal))
  await refreshClawd(io, false)
}

/** Back to the built-in text: the copy is saved as `.bak`, then emptied (an empty copy means the built-in text). Only an own copy in use. */
async function resetClawd(io: ClawdIo, part: BriefPart) {
  const p = (await readNow(io))[part]
  if (p === undefined || p.source !== 'own') return
  const bak = `${p.path}.bak`
  const text = await io.briefing.read(p.path).catch(() => undefined)
  if (text === undefined) return say(io, { text: `Could not read ${p.path}, so it was left as it is.` })
  try { await io.write(bak, text) } catch { return say(io, { text: `Could not save a backup at ${bak}, so your copy was left as it is.` }) }
  try { await io.write(p.path, '') } catch { return say(io, { text: `Could not empty ${p.path}, so your copy was left as it is. A backup is at ${bak}.` }) }
  await say(io, { text: `Back to the built-in text from your next session or /clear. Your copy is saved as ${bak}.` })
  await refreshClawd(io, false)
}

export type ClawdActions = {
  editClawd: (part: BriefPart, isTerminal: boolean) => Promise<unknown>
  resetClawd: (part: BriefPart) => Promise<unknown>
}

export const clawdActions = (io: ClawdIo): ClawdActions => ({
  editClawd: (part, isTerminal) => editClawd(io, part, isTerminal),
  resetClawd: part => resetClawd(io, part),
})

